mapper.select:
SELECT COUNT(*)
  FROM TB_CODE_DATA D
  JOIN TB_TERMS T ON T.DICT_ID = D.DICT_ID AND T.CODE_GRP = D.CODE_GRP AND T.CODE_TP = 'HIER' AND T.PARENT_CODE_GRP = #{codeGrp}
 WHERE D.DICT_ID = #{dictId} AND D.PARENT_CODE_VAL = #{codeVal}

SELECT D.CODE_ID as id, D.CODE_GRP as codeGrp, D.CODE_VAL as codeVal
  FROM TB_CODE_DATA D
  JOIN TB_TERMS T ON T.DICT_ID = D.DICT_ID AND T.CODE_GRP = D.CODE_GRP AND T.CODE_TP = 'HIER' AND T.PARENT_CODE_GRP = #{codeGrp}
 WHERE D.DICT_ID = #{dictId} AND D.PARENT_CODE_VAL = #{codeVal}

SELECT SUB_CODE_GRP FROM TB_CODE_INTEG
 WHERE DICT_ID = #{dictId} AND CODE_GRP = #{codeGrp}
 ORDER BY SORT_ORDER, SUB_CODE_GRP

SELECT TERMS_ID as "termsId", TERMS_NM as "termsNm", CODE_GRP as "codeGrp", DICT_ID as "dictId",
       COALESCE(CODE_TP, 'SINGLE') as "codeTp", COALESCE(PARENT_CODE_GRP, '') as "parentCodeGrp"
  FROM TB_TERMS WHERE TERMS_ID = #{termsId}
